  <process id="password_change" name="密码变更流程" isExecutable="true">

    <startEvent id="start" name="提交申请" />

    <userTask id="admin_review" name="系统管理员审核">
      <extensionElements>
        <flowable:taskListener event="create"
          delegateExpression="${candidateAssignmentListener}" />
        <flowable:properties>
          <flowable:property name="candidateType" value="ROLE" />
          <flowable:property name="candidateConfig" value="{&quot;roleIds&quot;:[1]}" />
          <flowable:property name="eventHandler" value="password_change" />
        </flowable:properties>
      </extensionElements>
    </userTask>

    <endEvent id="end" name="结束" />

    <sequenceFlow id="flow_start_to_review" sourceRef="start" targetRef="admin_review" name="提交审核" />
    <sequenceFlow id="flow_review_to_end" sourceRef="admin_review" targetRef="end" name="审核完成" />

  </process>

  <bpmndi:BPMNDiagram id="BPMNDiagram_password_change">
    <bpmndi:BPMNPlane bpmnElement="password_change" id="BPMNPlane_password_change">
      <bpmndi:BPMNShape bpmnElement="start" id="BPMNShape_start">
        <omgdc:Bounds height="30" width="30" x="100" y="163" />
      </bpmndi:BPMNShape>
      <bpmndi:BPMNShape bpmnElement="admin_review" id="BPMNShape_admin_review">
        <omgdc:Bounds height="80" width="100" x="230" y="138" />
      </bpmndi:BPMNShape>
      <bpmndi:BPMNShape bpmnElement="end" id="BPMNShape_end">
        <omgdc:Bounds height="28" width="28" x="430" y="164" />
      </bpmndi:BPMNShape>
      <bpmndi:BPMNEdge bpmnElement="flow_start_to_review" id="BPMNEdge_flow_start_to_review">
        <omgdi:waypoint x="130" y="178" />
        <omgdi:waypoint x="230" y="178" />
      </bpmndi:BPMNEdge>
      <bpmndi:BPMNEdge bpmnElement="flow_review_to_end" id="BPMNEdge_flow_review_to_end">
        <omgdi:waypoint x="330" y="178" />
        <omgdi:waypoint x="430" y="178" />
      </bpmndi:BPMNEdge>
    </bpmndi:BPMNPlane>
